import React, { useState } from 'react';
import Dashboard from './components/Dashboard'; // Ensure your path is correct
import VoiceWeb from './components/VoiceWeb'; // The new high-density UI

function App() {
    // 'dashboard' is the starting page
    const [currentPage, setCurrentPage] = useState('dashboard');

    // This state stores the PNR generated by the Voice AI to auto-fill the dashboard
    const [latestPnr, setLatestPnr] = useState('');

    /**
     * The Master Navigation Function
     * @param {string} target - The page to go to ('dashboard' or 'voiceweb')
     * @param {string} pnr - (Optional) The PNR generated by the AI
     */
    const handleNavigation = (target, pnr = '') => {
        console.log(`Navigating to: ${target}`);

        if (pnr) {
            setLatestPnr(pnr);
            console.log(`PNR captured from Voice: ${pnr}`);
        }

        setCurrentPage(target);
    };

    return (
        <div className="App" style={{ margin: 0, padding: 0, height: '100vh' }}>
            {currentPage === 'dashboard' ? (
                /* When in Dashboard: 
                   1. We pass 'handleNavigation' so the "Voice Web" button works.
                   2. We pass 'latestPnr' so the dashboard can auto-fill the search bar.
                */
                <Dashboard 
                    onNavigate={handleNavigation} 
                    externalPnr={latestPnr} 
                />
            ) : (
                /* When in VoiceWeb:
                   1. We pass 'handleNavigation' so the AI can redirect back 
                      to the dashboard once the booking is complete.
                */
                <VoiceWeb 
                    onNavigate={handleNavigation} 
                />
            )}
        </div>
    );
}

export default App;
